<content>import type { Database } from "better-sqlite3";

export const up = (db: Database): void => {
  // Add multiplayer columns to game_runs table
  db.exec(`
    -- Add game_mode column (defaults to 'single' for existing records)
    ALTER TABLE game_runs ADD COLUMN game_mode TEXT NOT NULL DEFAULT 'single';

    -- Add winner_profile_id for multiplayer games (NULL for single-player)
    ALTER TABLE game_runs ADD COLUMN winner_profile_id TEXT;

    -- Add player2_color for multiplayer games (NULL for single-player)
    ALTER TABLE game_runs ADD COLUMN player2_color TEXT;

    -- Add index for game_mode to support filtering
    CREATE INDEX IF NOT EXISTS idx_game_runs_game_mode ON game_runs(game_mode);

    -- Add index for winner_profile_id
    CREATE INDEX IF NOT EXISTS idx_game_runs_winner_profile_id ON game_runs(winner_profile_id);
  `);
};

export const down = (db: Database): void => {
  // Remove indexes
  db.exec(`
    DROP INDEX IF EXISTS idx_game_runs_game_mode;
    DROP INDEX IF EXISTS idx_game_runs_winner_profile_id;
  `);

  // Note: SQLite doesn't support DROP COLUMN directly
  // In production, you'd need to recreate the table without these columns
  // For now, we'll leave them (they can be NULL/default)
};
