export const createInitialState = (
  settings: GameSettings,
  powerupTypes: PowerupType[],
  maxConcurrentFoods: number,
  gameMode: "single" | "multiplayer" = "single",
  player2Color?: string
): GameState => {
  const mid = Math.floor(settings.gridSize / 2);
  const quarter = Math.floor(settings.gridSize / 4);

  // Player 1 starts in left-middle area, moving right
  const snake: Cell[] = Array.from({ length: START_LENGTH }, (_, index) => ({
    x: quarter - index,
    y: mid
  }));

  const baseSpeed = settings.speed;
  const foods: FoodItem[] = [];

  // Base state
  const baseState = {
    gameMode,
    snake,
    foods,
    direction: "right" as Direction,
    pendingDirection: "right" as Direction,
    score: 0,
    status: "idle" as GameStatus,
    tickCount: 0,
    activeEffects: [],
    currentSpeed: baseSpeed,
    baseSpeed
  };

  // Add multiplayer-specific state
  if (gameMode === "multiplayer") {
    // Player 2 starts in right-middle area, moving left
    const player2Snake: Cell[] = Array.from({ length: START_LENGTH }, (_, index) => ({
      x: settings.gridSize - quarter + index,
      y: mid
    }));

    // Spawn minimum 2 foods for multiplayer
    const minFoods = Math.max(maxConcurrentFoods, 2);
    const allSnakeCells = [...snake, ...player2Snake];
    for (let i = 0; i < minFoods; i++) {
      foods.push(placeFood(allSnakeCells, foods, settings.gridSize, powerupTypes));
    }

    return {
      ...baseState,
      foods,
      player2Snake,
      player2Direction: "left",
      player2PendingDirection: "left",
      player2Color: player2Color || "#5BB9C2", // Default to blue
      deadPlayers: []
    };
  }

  // Single-player: spawn normal amount of foods
  for (let i = 0; i < maxConcurrentFoods; i++) {
    foods.push(placeFood(snake, foods, settings.gridSize, powerupTypes));
  }

  return baseState;
};
