import { useEffect } from "react";
import type { Direction, GameMode } from "../types/game";

type UseKeyboardArgs = {
  gameMode: GameMode;
  onDirection: (direction: Direction) => void;
  onPlayer2Direction?: (direction: Direction) => void;
  onTogglePause: () => void;
  onStart: () => void;
  onReset: () => void;
};

export const useKeyboard = ({ 
  gameMode,
  onDirection, 
  onPlayer2Direction,
  onTogglePause, 
  onStart, 
  onReset 
}: UseKeyboardArgs) => {
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const key = event.key.toLowerCase();

      if (["arrowup", "arrowdown", "arrowleft", "arrowright", "w", "a", "s", "d", " "].includes(key)) {
        event.preventDefault();
      }

      if (gameMode === "single") {
        // Single-player: both arrow keys AND WASD control P1
        if (key === "arrowup" || key === "w") onDirection("up");
        if (key === "arrowdown" || key === "s") onDirection("down");
        if (key === "arrowleft" || key === "a") onDirection("left");
        if (key === "arrowright" || key === "d") onDirection("right");
      } else {
        // Multiplayer: Arrow keys = P1, WASD = P2
        if (key === "arrowup") onDirection("up");
        if (key === "arrowdown") onDirection("down");
        if (key === "arrowleft") onDirection("left");
        if (key === "arrowright") onDirection("right");

        if (onPlayer2Direction) {
          if (key === "w") onPlayer2Direction("up");
          if (key === "s") onPlayer2Direction("down");
          if (key === "a") onPlayer2Direction("left");
          if (key === "d") onPlayer2Direction("right");
        }
      }

      if (key === "p" || key === " ") onTogglePause();
      if (key === "enter") onStart();
      if (key === "r") onReset();
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [gameMode, onDirection, onPlayer2Direction, onStart, onReset, onTogglePause]);
};
