  boardBackgroundColor?: string;
  snakeColor?: string;
  snakeHeadColor?: string;
  player2Color?: string;
  boardGridColor?: string;
};

const toKey = (cell: Cell): string => `${cell.x}:${cell.y}`;

export const GameBoard = ({
  gridSize,
