import { Box, Container, Stack, Typography } from "@mui/material";
import { ActionButton } from "../shared/ActionButton";
import { Panel } from "../shared/Panel";
import { approvedIcons } from "../../theme/approvedIcons";
import type { GameMode, Player } from "../../types/game";

type GameOverScreenProps = {
  score: number;
  gameMode?: GameMode;
  winner?: Player | "tie";
  playerName?: string;
  onRestart: () => void;
};

export const GameOverScreen = ({ 
  score, 
  gameMode = "single",
  winner,
  playerName,
  onRestart 
}: GameOverScreenProps) => {
  const getTitle = () => {
    if (gameMode === "single") {
      return "Game Over";
    }
    if (winner === "tie") {
      return "It's a Tie!";
    }
    if (winner === "p1") {
      return `${playerName || "Player 1"} Wins!`;
    }
    if (winner === "p2") {
      return "Guest Player 2 Wins!";
